<?php
require_once __DIR__.'/../src/db.php';
function simulate_usage(): never { fwrite(STDERR,"Usage: php tools/simulate_hikers.php --scenario=normal_walk [--base-url=http://127.0.0.1:8000/api] OR --gpx=file.gpx [--speed=1]\n");exit(2); }
$args=getopt('', ['scenario:','gpx:','speed:','base-url:']);
if(!simulator_allowed(active_mode())){fwrite(STDERR,"Simulator refused: active mode is LIVE.\n");exit(3);}
$url=(string)($args['base-url']??'http://127.0.0.1:8000/api');$parts=parse_url($url);
if(!$parts||!in_array(strtolower((string)($parts['host']??'')),['127.0.0.1','localhost','::1'],true)||!in_array((int)($parts['port']??80),[80,8000,8001,8002,8080],true)){fwrite(STDERR,"Simulator target must be a local loopback API URL.\n");exit(2);}
$endpoint=rtrim($url,'/').'/bridge/ingest';$profile=db_profile('demo');$token=(string)(config()['bridge_tokens']['demo']??config()['bridge_token']??'');if($token===''){fwrite(STDERR,"Demo bridge token is not configured.\n");exit(2);}
$send=function(array $packet)use($endpoint,$token){$ctx=stream_context_create(['http'=>['method'=>'POST','header'=>"Content-Type: application/json\r\nX-Bridge-Token: $token\r\n",'content'=>json_encode($packet,JSON_THROW_ON_ERROR),'ignore_errors'=>true,'timeout'=>5]]);$result=file_get_contents($endpoint,false,$ctx);$status=$http_response_header[0]??'No HTTP response';echo $status."\n";if($result===false)throw new RuntimeException('Local API request failed');$json=json_decode($result,true);if(str_contains($status,' 4')||str_contains($status,' 5'))throw new RuntimeException((string)($json['error']??'API rejected packet'));};
$packet=function(int $seq,float $lat,float $lon,array $flags=[],string $path='DIRECT'){$uplinkFlags=array_merge(['link_lost'=>false,'low_battery'=>false,'emergency'=>false,'turn_back_received'=>false,'test_mode'=>false],$flags);$r=['base_id'=>'BASE','path_type'=>$path,'rssi_dbm'=>-80,'snr_db'=>8.5];if($path==='CHECKPOINT_RELAY'){$r['checkpoint_id']='CHK';$r['checkpoint_rssi_dbm']=-92;$r['relay_hop_delay_ms']=110;}return ['uplink'=>['node_id'=>'H1','sequence_number'=>$seq,'latitude'=>$lat,'longitude'=>$lon,'gps_accuracy_m'=>7.5,'satellite_count'=>7,'battery_level'=>84,'flags'=>$uplinkFlags],'reception'=>$r,'is_demo'=>true];};
try {
 if(isset($args['scenario'])){$file=__DIR__.'/scenarios/'.basename((string)$args['scenario']).'.json';if(!is_file($file))throw new RuntimeException('Scenario not found');$scenario=json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);foreach($scenario as $step){$flags=$step['flags']??[];$send($packet((int)$step['sequence_number'],(float)$step['latitude'],(float)$step['longitude'],$flags,(string)($step['path_type']??'DIRECT')));usleep((int)($step['delay_ms']??0)*1000);}}
 elseif(isset($args['gpx'])){$file=(string)$args['gpx'];if(!is_file($file))throw new RuntimeException('GPX file not found');$speed=(float)($args['speed']??1);if(!is_finite($speed)||$speed<=0||$speed>100)throw new RuntimeException('speed multiplier must be >0 and <=100');$xml=simplexml_load_file($file);if(!$xml)throw new RuntimeException('Invalid GPX XML');$seq=1;foreach($xml->xpath('//*[local-name()="trkpt"]')?:[] as $pt){$lat=(float)$pt['lat'];$lon=(float)$pt['lon'];$send($packet($seq++,$lat,$lon));usleep((int)(1000/$speed)*1000);}}
 else simulate_usage();
}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
